// Общий код для проверок /admin/support (S-02): строки по имени кандидата, меню строки, трасса «מסלול ביקורת».
// Только чтение. Побочный эффект открытия трассы — запись в журнал доступа SA (норма, как в audit-trail-534912).
import { Locator, Page, Response } from '@playwright/test';
import { expect } from '../../fixtures';
import { openWithApi, Api } from '../support/api';

export type ContentFlag = { category: string; offset_ms: number | null };
export type TrailAttempt = {
  id: string;
  invite_id: string;
  attempt_type: string;
  status: string;
  ended_at?: string | null;
  end_reason?: string | null;
  duration_seconds?: number | null;
  content_flags?: ContentFlag[] | null;
};
export type TrailInvite = { id: string } & Record<string, unknown>;
export type Trail = { invites: TrailInvite[]; attempts: TrailAttempt[] };

export const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Причины окончания (как на экране: словарь отчёта/панели). null → «—», неизвестная → «סיבה אחרת». */
export const END_REASON_LABEL: Record<string, string> = {
  next_step_achieved: 'נקבע צעד הבא',
  customer_refused: 'הלקוח המדומה סירב להמשיך',
  scenario_natural_end: 'התרחיש הגיע לסיומו',
  predefined_condition: 'התקיים תנאי סיום שהוגדר בתרחיש',
  candidate_ended: 'המועמד סיים את השיחה',
  duration_elapsed: 'הזמן שהוקצב לשיחה הסתיים',
  technical_failure: 'תקלה טכנית',
};
export const endReasonText = (code?: string | null) => (code ? END_REASON_LABEL[code] ?? 'סיבה אחרת' : '—');

/** «m:ss» (минуты без нуля), как в «משך». */
export const minSec = (seconds: number) => {
  const t = Math.max(0, Math.floor(seconds));
  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`;
};
/** «mm:ss» из миллисекунд (время отметки). */
export const clock = (ms: number) => {
  const t = Math.max(0, Math.floor(ms / 1000));
  return `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`;
};
export const flagLabel = (category: string) => (category === 'offensive' ? 'פוגענית' : category === 'inappropriate' ? 'לא הולמת' : 'פוגענית או לא הולמת');
export const flagText = (category: string) => `בשיחה סומנה אמירה ${flagLabel(category)} של המועמד`;

/** /admin/support за все даты. Возвращает API-клиент сессии SA. */
export async function openSupport(admin: Page): Promise<Api> {
  const api = await openWithApi(admin, '/admin/support');
  await expect(admin.getByRole('heading', { level: 1, name: 'תמיכה ותפעול' })).toBeVisible();
  await admin.getByRole('combobox', { name: 'טווח תאריכים' }).selectOption({ label: 'כל התאריכים' });
  return api;
}

/** Строка таблицы по точному имени кандидата. */
export const supportRow = (page: Page, name: string): Locator =>
  page
    .getByTestId('support-row')
    .filter({ has: page.locator('td[data-label="מועמד/ת"]', { hasText: new RegExp(`^${escapeRe(name)}$`) }) })
    .first();

/** Открывает строку → меню «פעולות תמיכה עבור …» (меню остаётся открытым). */
export async function openRowMenu(page: Page, name: string): Promise<Locator> {
  const row = supportRow(page, name);
  await expect(row, `нет строки «${name}» в /admin/support (все даты) — нет данных`).toBeVisible({ timeout: 40_000 });
  await row.getByRole('button', { name: `פעולות תמיכה עבור ${name}` }).click();
  return row;
}

/** Панель «מסלול ביקורת» кандидата + ответ get_attempt_audit_trail. */
export async function openTrail(admin: Page, name: string) {
  const api = await openSupport(admin);
  await openRowMenu(admin, name);
  const item = admin.getByRole('menuitem', { name: 'מסלול ביקורת', exact: true });
  await expect(item, 'в меню строки нет «מסלול ביקורת»').toBeVisible();
  const responsePromise = admin.waitForResponse((r: Response) => r.url().includes('/rest/v1/rpc/get_attempt_audit_trail') && r.request().method() === 'POST');
  await item.click();
  const res = await responsePromise;
  const body = res.request().postDataJSON() as { p_candidate_id: string; p_reason: string };
  expect(res.status(), await res.text()).toBe(200);
  const trail = (await res.json()) as Trail;
  const drawer = admin.getByTestId('audit-trail-drawer');
  await expect(drawer).toBeVisible();
  await expect(drawer.getByText(name).first()).toBeVisible();
  return { api, drawer, trail, candidateId: body.p_candidate_id };
}
